#!/usr/bin/env bash
# deploy_kirilim_tf.sh — Bolum 03 (Kirilimlar) + Bolum 04 (Aksiyon) ana zaman seciciye UYAR.
#   server: yeni /api/bi/kokpit-kirilim (pencereli) + iyilestirme-hedefleri 'ay' param. shells: kanonik (KIRILIM_TF_UI_V1) tam-degistir.
set -e
cd /opt/krb-assessment
TS=$(date +%s)
echo "" | base64 -d > /tmp/patch_kirilim_tf.py
pick(){ for p in "./$1" "shells/$1" "public/$1"; do case "$p" in *backups*) continue;; esac; [ -f "$p" ] && { echo "$p"; return 0; }; done; return 1; }
SRV=$(pick server_container.mjs) || { echo "HATA: server yok"; exit 1; }
case "$SRV" in *backups*) echo "HATA: backups"; exit 1;; esac
echo "server: $(ls -la "$SRV" | awk '{print $NF, $5}')"
cp "$SRV" "$SRV.bak.$TS"
python3 /tmp/patch_kirilim_tf.py "$SRV"
node --check "$SRV" && echo "  ✓ server ok" || { echo "HATA: server syntax"; exit 1; }
grep -q "/api/bi/kokpit-kirilim" "$SRV" && echo "  ✓ kokpit-kirilim endpoint mevcut" || { echo "HATA: endpoint yok"; exit 1; }
grep -q "alici = 'KRB'" "$SRV" && echo "  ✓ SQL veri-degeri korundu" || echo "  UYARI: alici='KRB' yok"
# shells tam-degistir (kanonik = tum UI patchleri)
for F in shells/kokpit.html shells/kokpit2.html; do
  [ -f "$F" ] && cp "$F" "$F.bak.$TS"
  echo "" | base64 -d > "$F"
  grep -q 'KIRILIM_TF_UI_V1' "$F" && echo "  ✓ $F (Bolum 03/04 seciciye uyar)" || { echo "HATA: $F"; exit 1; }
done
echo "=== docker build + recreate ==="
docker build -t krb-assessment:secure . >/tmp/build.log 2>&1 && echo "build ok" || { echo "BUILD HATASI:"; tail -25 /tmp/build.log; exit 1; }
docker compose up -d --force-recreate krb-assessment && echo "recreate ok"
echo "BITTI. Bolum 03 (Kirilimlar) ve 04 (Aksiyon) artik ust zaman seciciye uyuyor."
